"""
NeuroScan -- deployment check for the v2 inference server (2026-10-07). Linux CPU, no data. Runs the server's own
inference.py (embedded verbatim) with the final model's weights on synthetic images, one thread, and reports peak
memory and time per request for the four input pathways: (1) with the exact Docker image versions (torch 2.4.1 /
torchvision 0.19.1 CPU wheels, numpy 1.26.4, pillow 10.4.0, installed to a separate folder), (2) with Kaggle's torch.
Question: does the ConvNeXt-Tiny server fit Render's 512 MB free tier?
"""
import os, subprocess, sys, shutil
from pathlib import Path
SRV = Path("/kaggle/working/srv")
(SRV / "models").mkdir(parents=True, exist_ok=True)
W = next(p for p in (Path("/kaggle/input/datasets/atik68/neuroscan-q-r30a-s123-weights/r30a_s123_weights.pt"),
                     Path("/kaggle/input/neuroscan-q-r30a-s123-weights/r30a_s123_weights.pt")) if p.exists())
os.symlink(W, SRV / "models/r30a_s123_weights.pt")
(SRV / "inference.py").write_text('"""\nNeuroScan web demo -- shared inference logic (v2: the evaluated final model and its input pathway).\n\nModel: the paper\'s final model, R30A s123 -- torchvision ConvNeXt-Tiny, classifier[2] -> Linear(768, 3), one\nsoftmax over normal / ischemic / hemorrhagic. Weights: models/r30a_s123_weights.pt (optimizer state removed;\nSHA-256 checked at start-up against EXPECTED_SHA256). It replaces the Phase O ResNet18 checkpoint, which was trained\non an earlier slice-level partition and never evaluated on the patient-level held-out cohorts.\n\nInput pathway -- the one the offline evaluation used, chosen per request from what was uploaded:\n  * CT, current slice + previous + next  -> channels (previous, current, next)       ["ct_adjacent_slices", evaluated]\n  * MRI, DWI + ADC of the same slice      -> channels (DWI, ADC, DWI)                 ["mri_dwi_adc", evaluated]\n  * anything else (one image only)        -> channels (image, image, image)          ["single_image", NOT evaluated\n    as a deployment pathway; Post-hoc experiment C2 measures how much it loses]. The response says which pathway ran\n    and carries a warning when it is not the evaluated one.\nEvery image is converted to 8-bit grayscale and resized to 224 x 224, exactly as in training.\n\nDecision rule -- the locked rule from the evaluation: 4-view test-time augmentation (identity, horizontal flip,\n+8 deg, -8 deg rotation), softmax averaged over views (raw probabilities), prediction = argmax(p_raw * (1, 0.574,\n0.574)). The class weights were fixed on validation data before the held-out cohorts were scored.\n\nDisplayed probabilities -- temperature-calibrated (p ~ p_raw^(1/T), renormalised; T_CT = 1.48, T_MRI = 0.80, fitted\non validation data and evaluated on the held-out cohorts). The decision uses the raw probabilities, as evaluated, so in\nrare borderline cases the predicted class is not the one with the largest displayed probability; the response then\nsets decision_note. Raw probabilities are returned as raw_prob_* for audit.\n\nMRI and hemorrhage: no hemorrhagic MRI source was available for training or evaluation, so an MRI request carries a\nwarning that hemorrhage on MRI is outside the evaluated scope.\n\nGrad-CAM [Selvaraju et al., 2017] on ConvNeXt stage 4 (features[7], 7 x 7 for a 224 input), identity view only, for\nthe predicted class, overlaid on the current CT slice or the DWI image; same display rule as before (suppress below\nthe image\'s 70th-percentile activation, rescale, bicubic upsample; outline at > 0.6 for ischemic / hemorrhagic).\nPost-hoc experiment C3 evaluates this display rule against lesion masks. It shows where the model\'s evidence is\nconcentrated, not a lesion boundary.\n\nMemory: the free hosting tier has 512 MB. The four TTA views run one at a time under inference_mode, and torch uses\none thread, to keep peak memory low.\n"""\nimport base64\nimport hashlib\nimport io\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom PIL import Image\nfrom torchvision import models, transforms\n\nMODELS_DIR = Path(__file__).parent / "models"\nWEIGHTS_FILE = MODELS_DIR / "r30a_s123_weights.pt"\nEXPECTED_SHA256 = "1e2db8a7431f1dddb2686dc34e6c013983d8d2117909e8887eeb3bfef8d368c8"\nMODEL_VERSION = "r30a_s123_convnext_tiny"\n\nTARGET_SIZE = (224, 224)\nVALID_LABELS = ("normal", "ischemic", "hemorrhagic")\nLABEL_TO_IDX = {"normal": 0, "ischemic": 1, "hemorrhagic": 2}\nCLASS_WEIGHTS = np.array([1.0, 0.574, 0.574])  # locked decision rule (normal, ischemic, hemorrhagic)\nTEMPERATURE = {"CT": 1.48, "MRI": 0.80}\nMODALITIES = ("CT", "MRI")\n\nPATHWAY_CT = "ct_adjacent_slices"\nPATHWAY_MRI = "mri_dwi_adc"\nPATHWAY_SINGLE = "single_image"\n\nDEVICE = torch.device("cpu")\ntorch.set_num_threads(1)\n\nNORMALIZE = transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])\n\n\nclass InputError(ValueError):\n    """The uploaded combination of images cannot be processed (shown to the user as a 400)."""\n\n\ndef _gray(image: Image.Image) -> Image.Image:\n    return image.convert("L").resize(TARGET_SIZE)\n\n\ndef build_input(modality: str, main: Image.Image, prev: Image.Image | None = None, nxt: Image.Image | None = None,\n                adc: Image.Image | None = None):\n    """Returns (merged RGB image, pathway name, base image for the overlay)."""\n    if modality not in MODALITIES:\n        raise InputError("modality must be CT or MRI.")\n    cur = _gray(main)\n    if modality == "CT":\n        if adc is not None:\n            raise InputError("An ADC image applies to MRI only.")\n        if (prev is None) != (nxt is None):\n            raise InputError("For CT context, upload both the previous and the next slice (or neither).")\n        if prev is not None:\n            return Image.merge("RGB", (_gray(prev), cur, _gray(nxt))), PATHWAY_CT, cur\n    else:\n        if prev is not None or nxt is not None:\n            raise InputError("Previous/next slices apply to CT only; for MRI upload DWI and ADC.")\n        if adc is not None:\n            return Image.merge("RGB", (cur, _gray(adc), cur)), PATHWAY_MRI, cur\n    return Image.merge("RGB", (cur, cur, cur)), PATHWAY_SINGLE, cur\n\n\ndef _looks_like_grayscale_scan(\n    image: Image.Image, max_mean_channel_diff: float = 8.0, min_midtone_fraction: float = 0.30\n) -> bool:\n    """Input-file check, not an anatomical or diagnostic-quality check: the model was trained only on grayscale\n    CT/MRI slices and has no "none of the above" output, so this flags the commonest wrong-file uploads (colour\n    photos; mostly-white documents or diagrams) before a meaningless result reaches an alert. Both must hold:\n    near-identical R/G/B per pixel, and >= 30% midtone pixels. It will not catch every unrelated image (e.g. a\n    grayscale, midtone-heavy X-ray of something else)."""\n    rgb = np.asarray(image.convert("RGB"), dtype=np.float32)\n    r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]\n    channel_diff = (np.abs(r - g) + np.abs(g - b) + np.abs(r - b)) / 3.0\n    if channel_diff.mean() > max_mean_channel_diff:\n        return False\n    gray = np.asarray(image.convert("L"), dtype=np.float32)\n    midtone_fraction = ((gray > 40) & (gray < 220)).mean()\n    return bool(midtone_fraction >= min_midtone_fraction)\n\n\ndef _tta_views(img: Image.Image):\n    yield img\n    yield transforms.functional.hflip(img)\n    yield transforms.functional.rotate(img, 8, fill=0)\n    yield transforms.functional.rotate(img, -8, fill=0)\n\n\ndef _to_tensor(img: Image.Image) -> torch.Tensor:\n    return NORMALIZE(transforms.functional.to_tensor(img))\n\n\ndef _build_convnext_tiny(num_classes: int) -> nn.Module:\n    model = models.convnext_tiny(weights=None)\n    model.classifier[2] = nn.Linear(model.classifier[2].in_features, num_classes)\n    return model\n\n\ndef _sha256(path: Path) -> str:\n    h = hashlib.sha256()\n    with open(path, "rb") as f:\n        for chunk in iter(lambda: f.read(1 << 20), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef calibrate(p_raw: np.ndarray, modality: str) -> np.ndarray:\n    z = np.power(np.clip(p_raw, 1e-12, 1.0), 1.0 / TEMPERATURE[modality])\n    return z / z.sum()\n\n\ndef decide(p_raw: np.ndarray) -> int:\n    return int(np.argmax(p_raw * CLASS_WEIGHTS))\n\n\nclass ThreeClassPipeline:\n    """Loads the final model once; call .predict(...) per request."""\n\n    def __init__(self):\n        digest = _sha256(WEIGHTS_FILE)\n        if digest != EXPECTED_SHA256:\n            raise RuntimeError(f"Model weights checksum mismatch ({digest[:12]}...); refusing to serve.")\n        # mmap + assign: the parameters are the memory-mapped checkpoint tensors themselves, so the weights are not\n        # held twice (state dict + model) -- about 110 MB less peak memory on the 512 MB tier.\n        ckpt = torch.load(WEIGHTS_FILE, map_location=DEVICE, mmap=True, weights_only=False)\n        with torch.device("meta"):\n            self.model = _build_convnext_tiny(len(VALID_LABELS))\n        self.model.load_state_dict(ckpt["model_state"], assign=True)\n        self.model.eval()\n        self.epoch = ckpt.get("epoch")\n        self.val_acc = ckpt.get("val_acc")\n        self.weights_sha256 = digest\n\n        # Grad-CAM on ConvNeXt stage 4. A tensor hook (registered only when the output requires grad) captures the\n        # gradient; safe as instance attributes because the pipeline is a process-wide singleton on one worker.\n        self._gradcam_activations = None\n        self._gradcam_gradients = None\n        self.model.features[7].register_forward_hook(self._save_activations)\n\n    def _save_activations(self, module, inputs, output):\n        self._gradcam_activations = output\n        if output.requires_grad:\n            output.register_hook(self._save_gradients)\n\n    def _save_gradients(self, grad):\n        self._gradcam_gradients = grad\n\n    def _grad_cam_overlay(self, merged_identity: Image.Image, base: Image.Image, class_idx: int, color,\n                          draw_boundary: bool) -> Image.Image:\n        x = _to_tensor(merged_identity).unsqueeze(0).to(DEVICE)\n        with torch.enable_grad():\n            x.requires_grad_(True)\n            self.model.zero_grad(set_to_none=True)\n            logits = self.model(x)\n            logits[0, class_idx].backward()\n        activations = self._gradcam_activations[0]  # (C, 7, 7)\n        gradients = self._gradcam_gradients[0]\n        weights = gradients.mean(dim=(1, 2))\n        cam = torch.relu((weights[:, None, None] * activations).sum(dim=0))\n        cam = (cam / (cam.max() + 1e-8)).detach().cpu().numpy()\n        threshold = np.percentile(cam, 70)\n        cam = np.clip((cam - threshold) / (1 - threshold + 1e-8), 0, 1)\n        cam_img = Image.fromarray((cam * 255).astype(np.uint8)).resize(TARGET_SIZE, Image.BICUBIC)\n        self.model.zero_grad(set_to_none=True)\n        return self._overlay_heatmap(base, cam_img, color, draw_boundary)\n\n    @staticmethod\n    def _risk_tier_color(prediction: str, prob_normal: float, prob_ischemic: float, prob_hemorrhagic: float):\n        """Same confidence tiers as webapp_php/includes/risk_tier.php (kept in sync by hand), applied to the\n        displayed (calibrated) probabilities, so the heatmap tint agrees with the badge."""\n        if prediction == "hemorrhagic":\n            if prob_hemorrhagic >= 0.55:\n                return (192, 57, 43)\n            return (230, 126, 34)\n        if prediction == "ischemic":\n            if prob_ischemic >= 0.90:\n                return (192, 57, 43)\n            if prob_ischemic >= 0.70:\n                return (230, 126, 34)\n            return (127, 140, 141)\n        if prediction == "normal" and prob_normal >= 0.80:\n            return (41, 128, 185)\n        return (127, 140, 141)\n\n    @staticmethod\n    def _boundary_mask(mask: np.ndarray, thickness: int = 2) -> np.ndarray:\n        eroded = mask.copy()\n        eroded[1:, :] &= mask[:-1, :]\n        eroded[:-1, :] &= mask[1:, :]\n        eroded[:, 1:] &= mask[:, :-1]\n        eroded[:, :-1] &= mask[:, 1:]\n        boundary = mask & ~eroded\n        for _ in range(thickness - 1):\n            dilated = boundary.copy()\n            dilated[1:, :] |= boundary[:-1, :]\n            dilated[:-1, :] |= boundary[1:, :]\n            dilated[:, 1:] |= boundary[:, :-1]\n            dilated[:, :-1] |= boundary[:, 1:]\n            boundary = dilated\n        return boundary\n\n    @staticmethod\n    def _overlay_heatmap(base_image: Image.Image, cam_img: Image.Image, color, draw_boundary: bool) -> Image.Image:\n        base_arr = np.asarray(base_image.convert("RGB"), dtype=np.float32)\n        cam_arr = np.asarray(cam_img, dtype=np.float32) / 255.0\n        tint = np.asarray(color, dtype=np.float32)\n        alpha = (cam_arr * 0.75)[..., None]\n        blended = base_arr * (1 - alpha) + tint * alpha\n        if draw_boundary:\n            boundary = ThreeClassPipeline._boundary_mask(cam_arr > 0.6, thickness=2)\n            blended[boundary] = tint\n        return Image.fromarray(blended.astype(np.uint8))\n\n    def predict(self, modality: str, image: Image.Image, prev: Image.Image | None = None,\n                nxt: Image.Image | None = None, adc: Image.Image | None = None) -> dict:\n        merged, pathway, base = build_input(modality, image, prev, nxt, adc)\n        views = list(_tta_views(merged))\n        with torch.inference_mode():\n            p_raw = np.mean([torch.softmax(self.model(_to_tensor(v).unsqueeze(0).to(DEVICE)), dim=1)[0].numpy()\n                             for v in views], axis=0)\n        p_cal = calibrate(p_raw, modality)\n        idx = decide(p_raw)\n        prediction = VALID_LABELS[idx]\n\n        uploads = [u for u in (image, prev, nxt, adc) if u is not None]\n        try:\n            likely_not_a_scan = not all(_looks_like_grayscale_scan(u) for u in uploads)\n        except Exception:\n            likely_not_a_scan = False\n\n        warnings = []\n        if pathway == PATHWAY_SINGLE:\n            warnings.append("Single image only: this is not the evaluated input pathway. For CT upload the previous "\n                            "and next slices; for MRI upload the matching ADC image.")\n        if modality == "MRI":\n            warnings.append("MRI: hemorrhage was not represented in training or evaluation; MRI results concern "\n                            "normal versus ischemic only.")\n        result = {\n            "prediction": prediction,\n            "prob_normal": float(p_cal[0]),\n            "prob_ischemic": float(p_cal[1]),\n            "prob_hemorrhagic": float(p_cal[2]),\n            "raw_prob_normal": float(p_raw[0]),\n            "raw_prob_ischemic": float(p_raw[1]),\n            "raw_prob_hemorrhagic": float(p_raw[2]),\n            "modality": modality,\n            "pathway": pathway,\n            "evaluated_pathway": pathway != PATHWAY_SINGLE,\n            "model_version": MODEL_VERSION,\n            "likely_not_a_scan": likely_not_a_scan,\n            "warnings": warnings,\n            "decision_note": None,\n        }\n        if int(np.argmax(p_cal)) != idx:\n            result["decision_note"] = ("The decision rule fixed during evaluation weights normal more heavily, so the "\n                                       "predicted class is not the one with the highest displayed probability.")\n        try:\n            color = self._risk_tier_color(prediction, *map(float, p_cal))\n            overlay = self._grad_cam_overlay(views[0], base, idx, color, prediction in ("ischemic", "hemorrhagic"))\n            buf = io.BytesIO()\n            overlay.save(buf, format="PNG")\n            result["heatmap_png_base64"] = base64.b64encode(buf.getvalue()).decode("ascii")\n        except Exception:\n            pass\n        return result\n\n\n_pipeline: ThreeClassPipeline | None = None\n\n\ndef get_pipeline() -> ThreeClassPipeline:\n    global _pipeline\n    if _pipeline is None:\n        _pipeline = ThreeClassPipeline()\n    return _pipeline\n')
(SRV / "probe.py").write_text('\nimport os, resource, sys, time, json\nimport numpy as np\nfrom PIL import Image\ndef rss():\n    with open("/proc/self/status") as f:\n        for l in f:\n            if l.startswith("VmRSS"):\n                return int(l.split()[1]) // 1024\nt0 = time.time()\nimport torch, torchvision\nout = {"torch": torch.__version__, "torchvision": torchvision.__version__, "numpy": np.__version__, "rss_after_import_mb": rss()}\nsys.path.insert(0, "/kaggle/working/srv")\nimport inference as inf\np = inf.get_pipeline()\nout["rss_after_load_mb"] = rss()\nout["load_s"] = round(time.time() - t0, 2)\nrng = np.random.default_rng(0)\nmk = lambda: Image.fromarray((rng.random((512, 512)) * 180 + 20).astype(np.uint8))\ntimes = {}\nfor name, args in (("ct_single", ("CT", mk())), ("ct_context", ("CT", mk(), mk(), mk())),\n                   ("mri_dwi_adc", ("MRI", mk(), None, None, mk())), ("mri_single", ("MRI", mk()))):\n    ts = []\n    for _ in range(5):\n        t = time.time(); r = p.predict(*args); ts.append(time.time() - t)\n        assert r["pathway"] and "heatmap_png_base64" in r\n    times[name] = [round(float(np.median(ts)), 2), round(max(ts), 2)]\nout["seconds_median_max_per_request"] = times\nout["rss_after_requests_mb"] = rss()\nout["peak_rss_mb"] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss // 1024\nprint("RESULT " + json.dumps(out), flush=True)\n')
env1 = dict(os.environ, PYTHONPATH="/tmp/docker_pkgs", OMP_NUM_THREADS="1")
r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--target", "/tmp/docker_pkgs", "torch==2.4.1",
                    "torchvision==0.19.1", "--index-url", "https://download.pytorch.org/whl/cpu"], capture_output=True, text=True)
print("pip torch:", r.returncode, r.stderr[-400:])
r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--target", "/tmp/docker_pkgs", "--no-deps",
                    "numpy==1.26.4", "pillow==10.4.0"], capture_output=True, text=True)
print("pip numpy/pillow:", r.returncode, r.stderr[-400:])
for name, env in (("docker_versions", env1), ("kaggle_default", dict(os.environ, OMP_NUM_THREADS="1"))):
    r = subprocess.run([sys.executable, str(SRV / "probe.py")], env=env, capture_output=True, text=True)
    print(f"== {name} (exit {r.returncode})")
    print(r.stdout[-3000:])
    print(r.stderr[-1500:])
print("Done.")
